from pathlib import Path
import json,sys,traceback
from playwright.sync_api import sync_playwright,expect
from book_test_helpers import seed,go,fixture,records,value,BASE
OUT=Path(__file__).resolve().parent/('evidence/baseline' if '--baseline' in sys.argv else 'evidence/current')
def backup_export(p):
 b=fixture();b['pages'][0]['body']='自己独立写的正文';b['pages'][0]['supplements']=[dict(text='SOURCE-SUPPLEMENT')];r=records();r[0]['visibility']='private';seed(p,books=[b],records=r);p.goto(BASE+'pages/m06-p11.html');snapshot=p.evaluate('PrototypePreferences.snapshot()');assert snapshot['books'][0]['pages'][0]['body']=='自己独立写的正文';assert 'SOURCE-SECRET' not in json.dumps(snapshot['books']) and 'SOURCE-SUPPLEMENT' not in json.dumps(snapshot['books']);p.locator('#backup').click();expect(p.locator('.prototype-toast')).to_contain_text('备份已创建');backup=p.evaluate("JSON.parse(localStorage.getItem('dujia-prototype-backup'))");assert backup['books'][0]['id']=='book-state'
def auto_backup(p):
 seed(p,books=[fixture()],records=records());go(p,15,'?id=book-state');p.evaluate("()=>{PrototypeUI.write('dujia-prototype-preferences',{autoBackup:true});PrototypeBooks.change('book-state',b=>b.name='自动备份的新书名');}");backup=p.evaluate("JSON.parse(localStorage.getItem('dujia-prototype-backup'))");assert backup['books'][0]['name']=='自动备份的新书名';p.evaluate("()=>{const rows=PrototypeRecords.all();rows[0].visibility='private';PrototypeUI.write('dujia-prototype-records',rows);}");backup=p.evaluate("JSON.parse(localStorage.getItem('dujia-prototype-backup'))");assert 'SOURCE-SECRET' not in json.dumps(backup['books']);p.evaluate("PrototypeBooks.remove('book-state')");assert p.evaluate("JSON.parse(localStorage.getItem('dujia-prototype-backup')).books.length")==0
def drafts_home(p):
 draft=fixture('book-draft');draft['status']='draft';draft['name']='还没完成的册';seed(p,books=[fixture(),draft],records=records());p.goto(BASE+'pages/m06-p04.html');p.get_by_role('button',name='还没完成的册 回忆册 · 继续编辑',exact=False).click();p.wait_for_url('**/m08-p04.html*');assert 'book-draft' in p.url;p.goto(BASE+'pages/m03-p02.html');expect(p.locator('.reading')).to_contain_text('共同测试册');p.locator('.reading').click();p.wait_for_url('**/m08-p15.html*');go(p,16,'?id=book-state&page=page-state');p.wait_for_function("JSON.parse(localStorage.getItem('dujia-prototype-books'))[0].lastPage==='page-state'");p.goto(BASE+'pages/m03-p02.html');p.locator('.reading').click();p.wait_for_url('**/m08-p16.html*');assert 'page-state' in p.url
def drafts_logout_delete(p):
 b=fixture();draft=fixture('book-draft');draft['status']='draft';seed(p,books=[b,draft],records=records());p.goto(BASE+'pages/m06-p11.html');assert len(p.evaluate('PrototypePreferences.snapshot().books'))==2 and len(p.evaluate('PrototypePreferences.snapshot(true).books'))==1;p.evaluate('PrototypePreferences.logout()');p.wait_for_url('**/m01-p01.html');assert len(value(p))==2;p.goto(BASE+'pages/m06-p11.html');p.evaluate("sessionStorage.setItem('dujia-prototype-fail-next','settings-account-delete')");assert p.evaluate("()=>{try{PrototypePreferences.deleteAccount();return false}catch{return true}}") is True;assert len(value(p))==2;p.evaluate('PrototypePreferences.deleteAccount()');p.wait_for_url('**/m01-p01.html');assert value(p)==[]
def resolver_parity(p):
 b=fixture();b['pages'] += [dict(id='work-page',chapterId='chapter-state',template='工坊作品',source=dict(kind='work',id='work-source')),dict(id='pet-page',chapterId='chapter-state',template='宠物成长',source=dict(kind='pet',id='pet-test:pet-source'))];seed(p,books=[b],records=records());p.evaluate("()=>{localStorage.setItem('dujia-prototype-works',JSON.stringify([{id:'work-source',name:'真实共同工坊',status:'ready',sourceKind:'diary',sourceIds:['source-state'],story:'WORK-SECRET',createdAt:1791158400000}]));localStorage.setItem('dujia-prototype-pet',JSON.stringify({id:'pet-test',status:'active',logs:[{id:'pet-source',type:'source',date:'2026-10-04',sourceId:'source-state',sourceKind:'record',text:'旧关联标题'}]}));}");go(p,15,'?id=book-state');in_book=p.evaluate("PrototypeBooks.exported('book-state')");p.goto(BASE+'pages/m06-p11.html');in_settings=p.evaluate('PrototypePreferences.snapshot().books[0]');assert in_book==in_settings and in_settings['pages'][1]['body']=='WORK-SECRET' and in_settings['pages'][2]['body']=='SOURCE-SECRET';p.evaluate("()=>{const rows=PrototypeRecords.all();rows[0].visibility='private';PrototypeUI.write('dujia-prototype-records',rows);}");shared=p.evaluate('PrototypePreferences.snapshot(true)');assert 'WORK-SECRET' not in json.dumps(shared['books']) and 'SOURCE-SECRET' not in json.dumps(shared['books']);assert not shared['works'];assert all(not page['supplements'] for page in shared['books'][0]['pages'])

def invalid_source_dates(p):
 seed(p,books=[fixture()],records=records());p.evaluate("()=>{localStorage.setItem('dujia-prototype-works',JSON.stringify([{id:'invalid-date-work',status:'ready',sourceKind:'free',createdAt:'not-a-date',story:'INVALID-WORK'}]));localStorage.setItem('dujia-prototype-anniversaries',JSON.stringify([{id:'invalid-anniversary',name:'不存在的日期',date:'2026-02-30'}]));localStorage.setItem('dujia-prototype-pet',JSON.stringify({id:'pet-test',status:'active',logs:[{id:'invalid-linked-date',type:'source',date:'2026-10-04',sourceKind:'anniversary',sourceId:'invalid-anniversary'}]}));}");p.goto(BASE+'pages/m06-p11.html');sources=p.evaluate('PrototypePreferences.bookSources()');assert not any(v['kind'] in ['work','pet'] for v in sources);assert len(p.evaluate('PrototypePreferences.snapshot(true).books'))==1

rows=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(headless=True,executable_path=r'C:\Program Files\Google\Chrome\Application\chrome.exe')
 for name,run in {'global-backup-export-books-and-private-mask':backup_export,'book-auto-backup-and-source-privacy-delete':auto_backup,'global-draft-and-home-continue-reading':drafts_home,'book-drafts-backup-logout-delete-rules':drafts_logout_delete,'book-setting-source-resolver-parity-and-private-mask':resolver_parity,'invalid-source-dates-do-not-break-book-backup':invalid_source_dates}.items():
  c=b.new_context(viewport={'width':390,'height':844});p=c.new_page();p.set_default_timeout(5000);errors=[];p.on('pageerror',lambda e:errors.append(str(e)))
  try:run(p);assert not errors,errors;row=dict(case=name,passed=True)
  except Exception:row=dict(case=name,passed=False,failure=traceback.format_exc()[-2000:])
  row.update(errors=errors,url=p.url);rows.append(row);print(('PASS ' if row['passed'] else 'FAIL ')+name,flush=True);c.close()
 b.close()
OUT.mkdir(parents=True,exist_ok=True);(OUT/'book-global-results.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
raise SystemExit(0 if all(v['passed'] for v in rows) else 1)
